"""
Universal Document Loaders for RAG Generator
Supports PDF, DOCX, TXT, Markdown, CSV, TSV, JSON, HTML, and Raw Text
"""

import os
import csv
import json
import hashlib
from typing import List, Dict, Any, Union, BinaryIO
from io import BytesIO, StringIO
from bs4 import BeautifulSoup
import pypdf
import docx

from rag_generator.core.models import Document


class DocumentLoader:
    """Universal Loader that automatically detects file format and parses content."""

    SUPPORTED_EXTENSIONS = {
        ".pdf": "pdf",
        ".docx": "docx",
        ".doc": "docx",
        ".txt": "text",
        ".md": "markdown",
        ".markdown": "markdown",
        ".csv": "csv",
        ".tsv": "tsv",
        ".json": "json",
        ".jsonl": "jsonl",
        ".html": "html",
        ".htm": "html",
    }

    @staticmethod
    def compute_sha256(content: Union[str, bytes]) -> str:
        """Compute SHA256 checksum of document content."""
        if isinstance(content, str):
            content = content.encode("utf-8", errors="ignore")
        return hashlib.sha256(content).hexdigest()

    @classmethod
    def load_from_file(cls, file_path: str) -> Document:
        """Load a single document from a filesystem path."""
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File not found: {file_path}")

        filename = os.path.basename(file_path)
        _, ext = os.path.splitext(filename.lower())
        file_type = cls.SUPPORTED_EXTENSIONS.get(ext, "text")

        with open(file_path, "rb") as f:
            file_bytes = f.read()

        return cls.load_from_bytes(file_bytes, filename=filename, file_type=file_type)

    @classmethod
    def load_from_bytes(
        cls,
        file_bytes: bytes,
        filename: str,
        file_type: str = "text",
    ) -> Document:
        """Parse bytes into a structured Document object."""
        _, ext = os.path.splitext(filename.lower())
        if ext in cls.SUPPORTED_EXTENSIONS:
            file_type = cls.SUPPORTED_EXTENSIONS[ext]

        sha256 = cls.compute_sha256(file_bytes)
        file_size = len(file_bytes)

        if file_type == "pdf":
            content, pages = cls._parse_pdf(file_bytes)
        elif file_type == "docx":
            content, pages = cls._parse_docx(file_bytes)
        elif file_type == "csv":
            content, pages = cls._parse_csv(file_bytes, delimiter=",")
        elif file_type == "tsv":
            content, pages = cls._parse_csv(file_bytes, delimiter="\t")
        elif file_type in ("json", "jsonl"):
            content, pages = cls._parse_json(file_bytes, is_jsonl=(file_type == "jsonl"))
        elif file_type == "html":
            content, pages = cls._parse_html(file_bytes)
        else:
            # Default plain text / markdown
            content, pages = cls._parse_text(file_bytes)

        metadata = {
            "file_size": file_size,
            "sha256": sha256,
            "page_count": len(pages) if pages else 1,
            "original_filename": filename,
        }

        return Document(
            filename=filename,
            file_type=file_type,
            content=content,
            metadata=metadata,
            pages=pages,
        )

    @classmethod
    def load_from_text(cls, text: str, title: str = "Pasted_Text.txt") -> Document:
        """Create a Document object directly from raw text content."""
        sha256 = cls.compute_sha256(text)
        return Document(
            filename=title,
            file_type="text",
            content=text,
            metadata={
                "file_size": len(text.encode("utf-8")),
                "sha256": sha256,
                "page_count": 1,
            },
            pages=[{"page_number": 1, "text": text}],
        )

    @staticmethod
    def _parse_pdf(file_bytes: bytes):
        """Extract text and page-by-page mapping from PDF."""
        stream = BytesIO(file_bytes)
        reader = pypdf.PdfReader(stream)
        pages_data = []
        full_text_parts = []

        for idx, page in enumerate(reader.pages):
            page_text = page.extract_text() or ""
            page_num = idx + 1
            if page_text.strip():
                pages_data.append({"page_number": page_num, "text": page_text})
                full_text_parts.append(f"--- Page {page_num} ---\n{page_text}")

        full_content = "\n\n".join(full_text_parts)
        if not full_content.strip():
            full_content = "[PDF with no extractable text or scanned images]"
            pages_data = [{"page_number": 1, "text": full_content}]

        return full_content, pages_data

    @staticmethod
    def _parse_docx(file_bytes: bytes):
        """Extract text and sections from Word docx."""
        stream = BytesIO(file_bytes)
        doc = docx.Document(stream)
        paragraphs = []
        for p in doc.paragraphs:
            if p.text.strip():
                paragraphs.append(p.text.strip())

        # Also extract text from tables
        for table in doc.tables:
            table_rows = []
            for row in table.rows:
                cells = [cell.text.strip() for cell in row.cells if cell.text.strip()]
                if cells:
                    table_rows.append(" | ".join(cells))
            if table_rows:
                paragraphs.append("\n".join(table_rows))

        full_content = "\n\n".join(paragraphs)
        pages_data = [{"page_number": 1, "text": full_content}]
        return full_content, pages_data

    @staticmethod
    def _parse_csv(file_bytes: bytes, delimiter: str = ","):
        """Extract structured representation from CSV/TSV."""
        text = file_bytes.decode("utf-8", errors="replace")
        reader = csv.reader(StringIO(text), delimiter=delimiter)
        rows = list(reader)
        if not rows:
            return "", []

        headers = rows[0]
        data_rows = rows[1:]

        formatted_lines = [f"Table Headers: {', '.join(headers)}"]
        for idx, row in enumerate(data_rows, 1):
            row_items = []
            for h, val in zip(headers, row):
                row_items.append(f"{h}: {val}")
            # If row has more columns than headers
            if len(row) > len(headers):
                for val in row[len(headers):]:
                    row_items.append(f"Extra: {val}")
            formatted_lines.append(f"Row {idx} -> " + ", ".join(row_items))

        full_content = "\n".join(formatted_lines)
        pages_data = [{"page_number": 1, "text": full_content}]
        return full_content, pages_data

    @staticmethod
    def _parse_json(file_bytes: bytes, is_jsonl: bool = False):
        """Extract readable text from JSON or JSONL."""
        text = file_bytes.decode("utf-8", errors="replace")
        if is_jsonl:
            lines = [l.strip() for l in text.splitlines() if l.strip()]
            records = []
            for l in lines:
                try:
                    records.append(json.loads(l))
                except Exception:
                    records.append({"raw_line": l})
            formatted = json.dumps(records, indent=2)
        else:
            try:
                parsed = json.loads(text)
                formatted = json.dumps(parsed, indent=2)
            except Exception:
                formatted = text

        pages_data = [{"page_number": 1, "text": formatted}]
        return formatted, pages_data

    @staticmethod
    def _parse_html(file_bytes: bytes):
        """Extract clean text hierarchy from HTML."""
        html_text = file_bytes.decode("utf-8", errors="replace")
        soup = BeautifulSoup(html_text, "html.parser")

        # Strip scripts, styles, noscript, svg
        for tag in soup(["script", "style", "noscript", "svg", "header", "footer", "nav"]):
            tag.decompose()

        title = soup.title.string.strip() if soup.title and soup.title.string else "Document"
        text = soup.get_text(separator="\n", strip=True)
        content = f"Title: {title}\n\n{text}"
        pages_data = [{"page_number": 1, "text": content}]
        return content, pages_data

    @staticmethod
    def _parse_text(file_bytes: bytes):
        """Extract plain text/markdown."""
        text = file_bytes.decode("utf-8", errors="replace")
        pages_data = [{"page_number": 1, "text": text}]
        return text, pages_data

"""
Embedding Providers for RAG Generator
Supports Local Sentence-Transformers, Fast TF-IDF / Cosine Vectorizer, and OpenAI API
"""

import os
from abc import ABC, abstractmethod
from typing import List, Optional
import numpy as np


class BaseEmbedder(ABC):
    """Abstract base class for text embedding models."""

    @abstractmethod
    def embed_texts(self, texts: List[str]) -> np.ndarray:
        """Embed a list of strings into an (N, D) float32 numpy array."""
        pass

    @abstractmethod
    def embed_query(self, query: str) -> np.ndarray:
        """Embed a single query string into a 1D float32 numpy array."""
        pass

    @property
    @abstractmethod
    def dimension(self) -> int:
        pass


class SentenceTransformerEmbedder(BaseEmbedder):
    """Local dense embedding model using sentence-transformers."""

    def __init__(self, model_name: str = "all-MiniLM-L6-v2"):
        from sentence_transformers import SentenceTransformer
        self.model_name = model_name
        self._model = SentenceTransformer(model_name)
        self._dimension = self._model.get_sentence_embedding_dimension()

    def embed_texts(self, texts: List[str]) -> np.ndarray:
        if not texts:
            return np.empty((0, self._dimension), dtype=np.float32)
        embeddings = self._model.encode(texts, convert_to_numpy=True, normalize_embeddings=True)
        return embeddings.astype(np.float32)

    def embed_query(self, query: str) -> np.ndarray:
        vec = self._model.encode([query], convert_to_numpy=True, normalize_embeddings=True)[0]
        return vec.astype(np.float32)

    @property
    def dimension(self) -> int:
        return self._dimension


class TFIDFEmbedder(BaseEmbedder):
    """
    Robust fallback embedder using Term Frequency-Inverse Document Frequency
    with sublinear term frequency scaling and L2 normalization.
    Guarantees dense vector search works under any offline constraints.
    """

    def __init__(self, max_features: int = 512):
        from sklearn.feature_extraction.text import TfidfVectorizer
        self.max_features = max_features
        self._vectorizer = TfidfVectorizer(
            max_features=max_features,
            sublinear_tf=True,
            norm="l2",
            stop_words="english",
            token_pattern=r"(?u)\b\w+\b",
        )
        self._is_fitted = False
        self._dimension = max_features

    def fit_and_embed(self, texts: List[str]) -> np.ndarray:
        if not texts:
            return np.empty((0, self._dimension), dtype=np.float32)
        matrix = self._vectorizer.fit_transform(texts).toarray()
        self._is_fitted = True
        self._dimension = matrix.shape[1]
        return matrix.astype(np.float32)

    def embed_texts(self, texts: List[str]) -> np.ndarray:
        if not self._is_fitted:
            return self.fit_and_embed(texts)
        if not texts:
            return np.empty((0, self._dimension), dtype=np.float32)
        matrix = self._vectorizer.transform(texts).toarray()
        return matrix.astype(np.float32)

    def embed_query(self, query: str) -> np.ndarray:
        if not self._is_fitted:
            # Fallback one-hot query vector
            return np.ones(self._dimension, dtype=np.float32) / np.sqrt(self._dimension)
        vec = self._vectorizer.transform([query]).toarray()[0]
        norm = np.linalg.norm(vec)
        if norm > 1e-8:
            vec = vec / norm
        return vec.astype(np.float32)

    @property
    def dimension(self) -> int:
        return self._dimension


class OpenAIEmbedder(BaseEmbedder):
    """Dense vector embedding using OpenAI API (text-embedding-3-small)."""

    def __init__(self, api_key: str, model_name: str = "text-embedding-3-small"):
        import openai
        self.client = openai.OpenAI(api_key=api_key)
        self.model_name = model_name
        self._dim = 1536

    def embed_texts(self, texts: List[str]) -> np.ndarray:
        if not texts:
            return np.empty((0, self._dim), dtype=np.float32)
        response = self.client.embeddings.create(input=texts, model=self.model_name)
        vectors = [item.embedding for item in response.data]
        arr = np.array(vectors, dtype=np.float32)
        # Normalize
        norms = np.linalg.norm(arr, axis=1, keepdims=True)
        norms[norms == 0] = 1.0
        return arr / norms

    def embed_query(self, query: str) -> np.ndarray:
        return self.embed_texts([query])[0]

    @property
    def dimension(self) -> int:
        return self._dim


def get_embedding_provider(
    model_name: str = "all-MiniLM-L6-v2",
    api_key: Optional[str] = None,
) -> BaseEmbedder:
    """Factory function to instantiate the best available embedding provider."""
    # Check if OpenAI is explicitly requested and key is present
    if (model_name.startswith("text-embedding") or model_name.startswith("openai")) and (api_key or os.getenv("OPENAI_API_KEY")):
        key = api_key or os.getenv("OPENAI_API_KEY")
        actual_model = "text-embedding-3-small" if "3" in model_name else "text-embedding-ada-002"
        return OpenAIEmbedder(api_key=key, model_name=actual_model)

    # Try sentence-transformers
    try:
        return SentenceTransformerEmbedder(model_name=model_name)
    except Exception as e:
        print(f"Warning: SentenceTransformer '{model_name}' could not be loaded ({e}). Falling back to TF-IDF embedder.")
        return TFIDFEmbedder()

"""
Sparse Lexical BM25 Index for High-Precision Keyword Retrieval
"""

import re
from typing import List, Tuple, Optional
from rank_bm25 import BM25Okapi
from rag_generator.core.models import Chunk


class BM25Index:
    """Okapi BM25 Index for lexical search over chunked documents."""

    def __init__(self):
        self.chunks: List[Chunk] = []
        self.tokenized_corpus: List[List[str]] = []
        self._bm25: Optional[BM25Okapi] = None

    @staticmethod
    def tokenize(text: str) -> List[str]:
        """Normalize and tokenize text into clean word tokens."""
        text = text.lower()
        # Keep alphanumeric words and common acronyms / hyphenated terms
        tokens = re.findall(r"\b[a-z0-9_-]+\b", text)
        return tokens

    def add_chunks(self, new_chunks: List[Chunk]) -> int:
        """Add chunks and rebuild the BM25 index."""
        if not new_chunks:
            return 0

        self.chunks.extend(new_chunks)
        for chunk in new_chunks:
            tokens = self.tokenize(chunk.content)
            self.tokenized_corpus.append(tokens)

        if self.tokenized_corpus:
            self._bm25 = BM25Okapi(self.tokenized_corpus)

        return len(new_chunks)

    def search(
        self,
        query: str,
        top_k: int = 5,
        min_score: float = 0.0,
    ) -> List[Tuple[Chunk, float]]:
        """Query the BM25 index and return ranked chunks with normalized scores."""
        if not self._bm25 or not self.chunks:
            return []

        query_tokens = self.tokenize(query)
        if not query_tokens:
            return []

        raw_scores = self._bm25.get_scores(query_tokens)
        max_score = max(raw_scores) if len(raw_scores) > 0 and max(raw_scores) > 0 else 1.0

        # Sort indices by score descending
        top_indices = sorted(range(len(raw_scores)), key=lambda i: raw_scores[i], reverse=True)[:top_k]

        results = []
        for idx in top_indices:
            raw_s = raw_scores[idx]
            if raw_s <= 0:
                continue
            # Normalize to [0.0, 1.0]
            norm_score = float(raw_s / max_score)
            if norm_score >= min_score:
                results.append((self.chunks[idx], norm_score))

        return results

    def count(self) -> int:
        return len(self.chunks)

"""
LLM Provider Abstraction supporting Local Grounded Synthesizer, OpenAI, Gemini, Claude, and Ollama
"""

import os
import re
import json
import urllib.request
import urllib.error
from abc import ABC, abstractmethod
from typing import List, Dict, Any, Optional

from rag_generator.core.models import Chunk


class BaseLLMProvider(ABC):
    """Abstract base class for LLM response generation."""

    @abstractmethod
    def generate_answer(
        self,
        question: str,
        context_chunks: List[Chunk],
        temperature: float = 0.1,
    ) -> str:
        """Generate a grounded answer given the question and context chunks."""
        pass

    @property
    @abstractmethod
    def provider_name(self) -> str:
        pass


class LocalGroundedSynthesizer(BaseLLMProvider):
    """
    Built-in High-Precision Local Grounded Synthesizer.
    Analyzes retrieved passages, scores sentence relevance, extracts verbatim supporting facts,
    and synthesizes a well-formatted grounded answer with source attribution tags.
    Works 100% offline with zero external API keys.
    """

    @property
    def provider_name(self) -> str:
        return "local_grounded_synthesizer"

    def generate_answer(
        self,
        question: str,
        context_chunks: List[Chunk],
        temperature: float = 0.1,
    ) -> str:
        if not context_chunks:
            return "No relevant context was retrieved to answer this question."

        q_terms = [w.lower() for w in re.findall(r"\b\w{2,}\b", question)]
        # Filter common stopwords
        stops = {
            "what", "when", "where", "which", "who", "whom", "whose", "why", "how",
            "is", "are", "was", "were", "be", "been", "being", "have", "has", "had",
            "do", "does", "did", "can", "could", "will", "would", "shall", "should",
            "the", "a", "an", "and", "or", "in", "on", "at", "to", "for", "with", "by", "of"
        }
        key_terms = [w for w in q_terms if w not in stops]

        # Extract scored sentences from all chunks
        candidate_facts = []
        for c_idx, chunk in enumerate(context_chunks, 1):
            sentences = re.split(r"(?<=[.!?])\s+|\n+", chunk.content)
            for s in sentences:
                s_clean = s.strip()
                if len(s_clean) < 15:
                    continue
                s_lower = s_clean.lower()
                # Compute overlap score
                matched_terms = [term for term in key_terms if term in s_lower]
                score = len(matched_terms)

                # Bonus for exact phrase matches or numbers/capitalized terms
                if len(matched_terms) > 1:
                    score += 1.5

                if score > 0:
                    candidate_facts.append({
                        "sentence": s_clean,
                        "score": score,
                        "chunk_idx": c_idx,
                        "source": chunk.source_name,
                        "page": chunk.page_number,
                    })

        if not candidate_facts:
            # Fallback to top chunk snippet if no specific sentence scored high
            top_c = context_chunks[0]
            summary = top_c.content[:400].strip()
            return (
                f"Based on **{top_c.source_name}** (Page {top_c.page_number}):\n\n"
                f"{summary}\n\n"
                f"*(Source: [{top_c.source_name}, p.{top_c.page_number}])* "
            )

        # Sort candidate facts by score descending
        candidate_facts.sort(key=lambda x: x["score"], reverse=True)

        # Select top unique sentences
        selected = []
        seen_texts = set()
        for fact in candidate_facts:
            normalized = re.sub(r"\W+", " ", fact["sentence"].lower()).strip()
            if normalized in seen_texts:
                continue
            seen_texts.add(normalized)
            selected.append(fact)
            if len(selected) >= 5:
                break

        # Synthesize organized answer
        lines = [
            f"Based on the provided documents, here is the answer regarding **{question}**:\n"
        ]

        for item in selected:
            sent = item["sentence"]
            # Ensure sentence ends with punctuation
            if not sent.endswith((".", "!", "?")):
                sent += "."
            lines.append(f"• {sent} *[Source: {item['source']}, p.{item['page']}]*")

        # Concluding summary
        top_src = selected[0]["source"]
        lines.append(f"\n*(Grounded directly from verified document source: {top_src})*")

        return "\n".join(lines)


class OpenAILLMProvider(BaseLLMProvider):
    """OpenAI API Provider (e.g. gpt-4o, gpt-4o-mini)."""

    def __init__(self, api_key: str, model_name: str = "gpt-4o-mini", api_base: Optional[str] = None):
        import openai
        self.model_name = model_name
        self.client = openai.OpenAI(api_key=api_key, base_url=api_base)

    @property
    def provider_name(self) -> str:
        return f"openai_{self.model_name}"

    def generate_answer(
        self,
        question: str,
        context_chunks: List[Chunk],
        temperature: float = 0.1,
    ) -> str:
        # Build structured context string
        context_str_parts = []
        for idx, c in enumerate(context_chunks, 1):
            context_str_parts.append(
                f"[Source {idx}: {c.source_name}, Page {c.page_number}]\n{c.content}"
            )
        formatted_context = "\n\n".join(context_str_parts)

        system_prompt = (
            "You are a rigorous, truthful Question-Answering assistant. "
            "Your task is to answer the user's question using ONLY the provided Source Documents below.\n"
            "STRICT RULES:\n"
            "1. Answer strictly based on the provided facts.\n"
            "2. If the context does not contain the answer, explicitly state: 'The provided documents do not contain information to answer this question.'\n"
            "3. Cite your sources using [Source X: DocumentName, p. Y] format after each factual claim.\n"
            "4. Do not speculate or introduce outside knowledge."
        )

        user_content = f"CONTEXT DOCUMENTS:\n{formatted_context}\n\nQUESTION: {question}"

        response = self.client.chat.completions.create(
            model=self.model_name,
            messages=[
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_content},
            ],
            temperature=temperature,
        )
        return response.choices[0].message.content or ""


class OllamaLLMProvider(BaseLLMProvider):
    """Local Ollama HTTP API provider."""

    def __init__(self, base_url: str = "http://localhost:11434", model_name: str = "llama3"):
        self.base_url = base_url.rstrip("/")
        self.model_name = model_name

    @property
    def provider_name(self) -> str:
        return f"ollama_{self.model_name}"

    def generate_answer(
        self,
        question: str,
        context_chunks: List[Chunk],
        temperature: float = 0.1,
    ) -> str:
        context_str = "\n\n".join([f"[{c.source_name} (p.{c.page_number})]: {c.content}" for c in context_chunks])
        prompt = (
            f"Context:\n{context_str}\n\n"
            f"Question: {question}\n\n"
            "Answer the question based strictly on the context above. Cite the source document."
        )
        payload = json.dumps({
            "model": self.model_name,
            "prompt": prompt,
            "stream": False,
            "options": {"temperature": temperature},
        }).encode("utf-8")

        req = urllib.request.Request(
            f"{self.base_url}/api/generate",
            data=payload,
            headers={"Content-Type": "application/json"},
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                data = json.loads(resp.read().decode("utf-8"))
                return data.get("response", "")
        except Exception as e:
            return f"Error communicating with Ollama ({self.base_url}): {e}"


def get_llm_provider(
    provider_name: str = "local_grounded",
    api_key: Optional[str] = None,
    model_name: Optional[str] = None,
    api_base: Optional[str] = None,
) -> BaseLLMProvider:
    """Factory to instantiate requested LLM provider with fallback."""
    provider_lower = (provider_name or "").lower()

    if "openai" in provider_lower:
        key = api_key or os.getenv("OPENAI_API_KEY")
        if key:
            model = model_name or "gpt-4o-mini"
            return OpenAILLMProvider(api_key=key, model_name=model, api_base=api_base)
        print("Notice: No OpenAI API Key found, using local grounded synthesizer.")

    if "ollama" in provider_lower:
        base = api_base or "http://localhost:11434"
        model = model_name or "llama3"
        return OllamaLLMProvider(base_url=base, model_name=model)

    # Default to built-in local grounded synthesizer
    return LocalGroundedSynthesizer()

"""
RAG Application Factory - Orchestrates runtime creation, lifecycle, and persistence of RAG apps
"""

import os
import shutil
import uuid
import re
from typing import Dict, List, Optional, Union
from rag_generator.core.models import (
    RAGAppConfig,
    RAGAppMetadata,
    Document,
)
from rag_generator.core.instance import RAGApplicationInstance


class RAGFactory:
    """Factory responsible for instantiating, discovering, and managing RAG applications."""

    def __init__(self, storage_root: str = "./data/apps"):
        self.storage_root = os.path.abspath(storage_root)
        os.makedirs(self.storage_root, exist_ok=True)
        self._instances: Dict[str, RAGApplicationInstance] = {}
        self._load_persisted_apps()

    def _slugify(self, text: str) -> str:
        """Create URL-safe slug from app name."""
        s = re.sub(r"[^\w\s-]", "", text.lower()).strip()
        s = re.sub(r"[-\s]+", "-", s)
        return s or "rag-app"

    def create_app(
        self,
        name: str,
        description: str = "",
        config_override: Optional[RAGAppConfig] = None,
        files: Optional[List[str]] = None,
        raw_texts: Optional[List[Dict[str, str]]] = None,
    ) -> RAGApplicationInstance:
        """
        Dynamically instantiate a new RAG Application over provided documents at runtime.
        """
        slug = self._slugify(name)
        short_id = uuid.uuid4().hex[:6]
        app_id = f"{slug}-{short_id}"

        if config_override:
            config = config_override
            config.app_id = app_id
            config.name = name
            if description:
                config.description = description
        else:
            config = RAGAppConfig(
                app_id=app_id,
                name=name,
                description=description or f"RAG Application for {name}",
            )

        # Instantiate isolated app pipeline
        instance = RAGApplicationInstance(config=config, storage_dir=self.storage_root)

        # Ingest files if provided
        if files:
            for file_path in files:
                if os.path.exists(file_path):
                    if os.path.isdir(file_path):
                        for root, _, fnames in os.walk(file_path):
                            for fn in fnames:
                                full_p = os.path.join(root, fn)
                                try:
                                    instance.ingest_file(full_p)
                                except Exception as e:
                                    print(f"Error ingesting {full_p}: {e}")
                    else:
                        try:
                            instance.ingest_file(file_path)
                        except Exception as e:
                            print(f"Error ingesting {file_path}: {e}")

        # Ingest raw text snippets if provided
        if raw_texts:
            for item in raw_texts:
                content = item.get("content", "")
                title = item.get("title", "Document.txt")
                if content.strip():
                    instance.ingest_raw_text(content, title=title)

        # Register in memory and save to disk
        self._instances[app_id] = instance
        instance.save_to_disk()

        return instance

    def get_app(self, app_id: str) -> Optional[RAGApplicationInstance]:
        """Fetch active application instance by ID."""
        if app_id in self._instances:
            return self._instances[app_id]

        # Check if exists on disk
        app_dir = os.path.join(self.storage_root, app_id)
        if os.path.isdir(app_dir):
            try:
                instance = RAGApplicationInstance.load_from_disk(app_dir, self.storage_root)
                self._instances[app_id] = instance
                return instance
            except Exception as e:
                print(f"Failed to load app {app_id} from disk: {e}")

        return None

    def list_apps(self) -> List[RAGAppMetadata]:
        """List metadata for all available applications."""
        result = []
        for app_id, inst in self._instances.items():
            result.append(inst.get_metadata())
        # Sort by updated_at descending
        result.sort(key=lambda x: x.updated_at, reverse=True)
        return result

    def delete_app(self, app_id: str) -> bool:
        """Delete application instance and its storage directory."""
        if app_id in self._instances:
            del self._instances[app_id]

        app_dir = os.path.join(self.storage_root, app_id)
        if os.path.exists(app_dir):
            shutil.rmtree(app_dir, ignore_errors=True)
            return True
        return False

    def _load_persisted_apps(self) -> None:
        """Discover and load apps previously created and saved in storage_root."""
        if not os.path.exists(self.storage_root):
            return

        for item in os.listdir(self.storage_root):
            app_dir = os.path.join(self.storage_root, item)
            if os.path.isdir(app_dir) and os.path.exists(os.path.join(app_dir, "config.json")):
                try:
                    instance = RAGApplicationInstance.load_from_disk(app_dir, self.storage_root)
                    self._instances[instance.app_id] = instance
                except Exception as e:
                    print(f"Failed to auto-load app in {item}: {e}")

